def get_prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def is_power_of_prime(n, p):
    if n <= 0:
        return False
    count = 0
    while n > 1 and n % p == 0:
        n //= p
        count += 1
    return n == 1, count

def solve_search():
    solutions = []
    MAX_VAL = 10

    print(f"Starting search for 1 <= m, n <= {MAX_VAL} with p >= 5.")

    for m in range(1, MAX_VAL + 1):
        for n in range(1, MAX_VAL + 1):
            X = m**2 + n
            Y = m + n**2

            if X <= 1 or Y <= 1:
                continue

            factors_X = get_prime_factorization(X)
            factors_Y = get_prime_factorization(Y)

            common_primes = set(factors_X.keys()) & set(factors_Y.keys())

            for p in common_primes:
                if p < 5:
                    continue

                # Check if X and Y are perfect powers of p
                is_X_power, A = is_power_of_prime(X, p)
                is_Y_power, B = is_power_of_prime(Y, p)

                if is_X_power and is_Y_power:
                    # Check exponent conditions
                    if A > 1 and B > 1:
                        # Check modular constraint derived by W2: m(m^3 + 1) = 0 (mod p)
                        # We need m * (m**3 + 1) % p == 0
                        if (m * (m**3 + 1)) % p == 0:
                            solutions.append((m, n, p))
                            print(f"Found solution: ({m}, {n}, {p}) | X={X}={p}^{A}, Y={Y}={p}^{B}. Modulo check passed.")

    return solutions

found_solutions = solve_search()
print("\n--- Summary ---")
if found_solutions:
    print("Solutions found satisfying all conditions:")
    for sol in found_solutions:
        print(sol)
else:
    print("No solutions found satisfying all conditions for p >= 5 and m, n <= 10.")
